const server = await preview({
  preview: {
    host: "127.0.0.1",
    port: 5177,
    strictPort: true,
    proxy: { "/api": { target: "http://127.0.0.1:18080", changeOrigin: true } },
  },
});
const browser = await chromium.launch({
  headless: true,
  ...(process.env.SMOKE_BROWSER === "chromium"
    ? {}
    : { channel: process.env.SMOKE_BROWSER || "msedge" }),
});
const failures = [];
let activePage;
async function connect(role) {
  const context = await browser.newContext({
    viewport: { width: 1440, height: 1000 },
  });
  const page = await context.newPage();
  activePage = page;
  page.on("pageerror", (error) => failures.push(error.message));
  page.on("request", (request) => {
    const url = new URL(request.url());
    if (
      url.pathname.startsWith("/api/") &&
      ((url.pathname === "/api/encounters" && request.method() === "GET") ||
        /\/visits\/\d+\/complete$/.test(url.pathname))
    )
      failures.push(
        `Unsupported API called: ${request.method()} ${url.pathname}`,
      );
  });
  await page.goto("http://127.0.0.1:5177/connect");
  await page
    .getByLabel("로그인 ID", { exact: true })
    .fill(fixture.accounts[role].username);
  await page
    .getByLabel("비밀번호", { exact: true })
    .fill(fixture.accounts[role].password);
  await page.getByRole("button", { name: "로그인", exact: true }).click();
  await expect(
    page.getByRole("heading", { name: `테스트 ${role}님, 안녕하세요` }),
  ).toBeVisible();
  record(`Real password login, server JWT and ${role} menu`);
  return { page, context };
}

